def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    if n == 0:
        return 1

    chars = list(dict.fromkeys(alphabet))
    k = len(chars)

    # Deduplicate banned strings
    words = set(banned)
    if not words:
        return pow(k, n, MOD)

    # Build Aho-Corasick trie
    nxt = [{}]
    term = [False]
    depth = [0]
    for w in words:
        node = 0
        for ch in w:
            c = next.get(node, {}).get(ch)
            if c is None:
                nxt[node][ch] = len(nxt)
                nxt.append({})
                term.append(False)
                depth.append(depth[node] + 1)
                c = nxt[node][ch]
            node = c
        term[node] = True

    m = len(nxt)

    # Build failure links (BFS)
    fail = [0] * m
    queue = []
    for ch, c in nxt[0].items():
        fail[c] = 0
        queue.append(c)

    head = 0
    while head < len(queue):
        r = queue[head]
        head += 1
        for ch, u in nxt[r].items():
            queue.append(u)
            f = fail[r]
            while f and ch not in nxt[f]:
                f = fail[f]
            fail[u] = nxt[f].get(ch, 0) if nxt[f].get(ch, 0) != u else 0
            # If child transition from fail points to u itself (self-loop on root path),
            # standard AC just uses that; for root children it is 0 anyway.
            if fail[u] == u:
                fail[u] = 0
            term[u] = term[u] or term[fail[u]]

    # Full transition table: go(state, ch) resolves via fail links
    def go(state, ch):
        s = state
        while s and ch not in nxt[s]:
            s = fail[s]
        return nxt[s].get(ch, 0)

    # Transition matrix over non-terminal states; terminal states are dead ends.
    alive = [i for i in range(m) if not term[i]]
    index = {s: i for i, s in enumerate(alive)}
    d = len(alive)

    # Matrix A[i][j] = number of chars taking alive state alive[i] to alive[j]
    A = [[0] * d for _ in range(d)]
    for s in alive:
        for ch in chars:
            t = go(s, ch)
            if not term[t] and t in index:
                A[index[s]][index[t]] = (A[index[s]][index[t]] + 1) % MOD

    def mat_mul(X, Y):
        Z = [[0] * d for _ in range(d)]
        for i in range(d):
            Xi = X[i]
            Zi = Z[i]
            for l in range(d):
                a = Xi[l]
                if a:
                    Yl = Y[l]
                    for j in range(d):
                        if Yl[j]:
                            Zi[j] = (Zi[j] + a * Yl[j]) % MOD
        return Z

    def mat_pow(M, e):
        R = [[0] * d for _ in range(d)]
        for i in range(d):
            R[i][i] = 1
        while e:
            if e & 1:
                R = mat_mul(R, M)
            M = mat_mul(M, M)
            e >>= 1
        return R

    B = mat_pow(A, n)

    # Start at root (state 0), sum over all ending states
    v = [0] * d
    if 0 in index:
        v[index[0]] = 1
    ans = 0
    for i in range(d):
        if v[i]:
            row = B[i]
            for j in range(d):
                ans = (ans + v[i] * row[j]) % MOD
    return ans % MOD
